        )
    except BaseException as e:
        await asyncio.gather(
            *[
                run_manager.on_llm_error(e, response=LLMResult(generations=[]))
                for run_manager in run_managers
            ]
        )
        raise e
    flattened_outputs = output.flatten()
    await asyncio.gather(
        *[
