const computeLinks = (function(){
  const path=require('path');
  const loader=require('./out/vs/loader');
  function fileUriFromPath(p){let s=p.replace(/\\/g,'/');if(s[0]!=='/')s='/'+s;return encodeURI('file://'+s).replace(/#/g,'%23');}
  const base=fileUriFromPath(path.join(__dirname,'out'));
  return new Promise((resolve,reject)=>{
    loader.config({nodeRequire:require,nodeMain:__filename,baseUrl:base,catchError:true});
    loader(['vs/editor/common/languages/linkComputer'],mod=>resolve(mod.computeLinks),reject);
  });
})();
computeLinks.then(fn=>{
  class T{constructor(lines){this._l=lines;}getLineCount(){return this._l.length;}getLineContent(n){return this._l[n-1];}}
  const cases=[
    "// Copy this link(https://regexper.com/#%2F''%2F).",
    "'https://example.com/#a'b'c'", // wrapped in single quotes should terminate at trailing quote
    "`https://example.com/#a'b`", // backtick-wrapped allows '
    "\"https://example.com/#a'b\"", // double-quote-wrapped allows '
  ];
  for(const line of cases){
    const links=fn(new T([line]));
    console.log(line,'\n=>',links.map(l=>l.url));
  }
}).catch(e=>{console.error('load error',e)});
